// Function node (n8n) - ChatGPT çıktısını temizler, onarır, parse eder ve gerçek JSON döner.
// Kullanım: ChatGPT node'dan sonra bağla. ChatGPT çıktısı items[0].json.content veya items[0].json.choices[0].message.content gibi olabilir.

const rawFrom = items[0].json.content
  || (items[0].json.choices && items[0].json.choices[0] && items[0].json.choices[0].message && items[0].json.choices[0].message.content)
  || JSON.stringify(items[0].json);

// ensure string
let s = String(rawFrom);

// 1) Remove common code fences and leading "```json" etc.
s = s.replace(/```json\s*/gi, "").replace(/```/g, "").trim();

// 2) If assistant prepended text before JSON, extract substring from first { to last }
//    fallback: from first [ to last ] if no object found.
const firstObj = s.indexOf('{');
const lastObj  = s.lastIndexOf('}');
const firstArr = s.indexOf('[');
const lastArr  = s.lastIndexOf(']');

let candidate = s;
if (firstObj !== -1 && lastObj !== -1 && lastObj > firstObj) {
  candidate = s.substring(firstObj, lastObj + 1);
} else if (firstArr !== -1 && lastArr !== -1 && lastArr > firstArr) {
  candidate = s.substring(firstArr, lastArr + 1);
}

// 3) Convert decimal dots to commas (e.g. 340.50 -> 340,50)
candidate = candidate.replace(/(\d+)\.(\d{2})(?=[\s"\}\]\,])/g, "$1,$2");

// 4) Remove percent signs inside quoted values (e.g. "%10" -> "10")
candidate = candidate.replace(/"(\s*)%?(\d+(?:[.,]\d+)?)%?(\s*)"/g, "\"$2\"");

// 5) Remove trailing commas before } or ] (e.g. {"a":1,} -> {"a":1})
candidate = candidate.replace(/,(\s*[}\]])/g, "$1");

// 6) Try to auto-balance braces if JSON truncated
function balanceCount(str, openChar, closeChar){
  let n = 0;
  for (let ch of str) {
    if (ch === openChar) n++;
    else if (ch === closeChar) n--;
  }
  return n;
}
let braceDiff = balanceCount(candidate, '{', '}');
while (braceDiff > 0) { candidate += '}'; braceDiff--; }
while (braceDiff < 0) {
  candidate = candidate.replace(/}\s*$/, '');
  braceDiff = balanceCount(candidate, '{', '}');
}

// 7) Final lightweight cleanup
candidate = candidate.trim();

// 8) Attempt parse
let parsed = null;
try {
  parsed = JSON.parse(candidate);
} catch (err) {
  const match = candidate.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch (err2) {
      throw new Error("JSON parse failed after cleaning. Error: " + err2.message + "\nCleaned snippet (first 1200 chars):\n" + candidate.slice(0,1200));
    }
  } else {
    throw new Error("No JSON object found in ChatGPT output. Cleaned snippet (first 1200 chars):\n" + candidate.slice(0,1200));
  }
}

// 9) Ensure required top-level keys exist
if (typeof parsed !== 'object' || parsed === null) {
  throw new Error("Parsed value is not an object.");
}
parsed.belge_tarihi = parsed.belge_tarihi ?? "";
parsed.fatura_no = parsed.fatura_no ?? "";
parsed.faturayi_kesen = parsed.faturayi_kesen ?? { adi: "", TCKN_VKN: "" };
parsed.fatura_kesilen = parsed.fatura_kesilen ?? { adi: "", TCKN_VKN: "" };
parsed.urunler = Array.isArray(parsed.urunler) ? parsed.urunler : [];

// Ensure each product has required fields
parsed.urunler = parsed.urunler.map(u => {
  const convertDots = (v) => typeof v === "string" ? v.replace(/(\d+)\.(\d{2})/g, "$1,$2") : v;
  return {
    adi: (u.adi ?? "").toString(),
    miktar: convertDots(u.miktar ?? "").toString(),
    birim_fiyat: convertDots(u.birim_fiyat ?? "").toString(),
    kdv_miktari: convertDots(u.kdv_miktari ?? "").toString(),
    odenecek_tutar: convertDots(u.odenecek_tutar ?? "").toString(),
    kur_carpani: convertDots(u.kur_carpani ?? "").toString(),
    doviz_birimi: (u.doviz_birimi ?? "TL").toString()
  };
});

// 10) Return standardized JSON
return [{ json: parsed }];

