const raw = items[0].json.content[0].text;
const clean = raw
  .replace(/```json\n?/g, '')
  .replace(/```/g, '')
  .trim();

return [{ json: JSON.parse(clean) }];

const data = items[0].json;

let dovizBirimi;
let faturaStr = data.belge_tarihi;

if (Array.isArray(data.urunler) && data.urunler.length > 0 && data.urunler[0].doviz_birimi) {
  dovizBirimi = data.urunler[0].doviz_birimi;
} else if (data.doviz_birimi) {
  dovizBirimi = data.doviz_birimi;
} else {
  dovizBirimi = "TL";
}

if (!dovizBirimi || dovizBirimi === "TL" || dovizBirimi === "TRY") {
  return [{
    json: {
      ...data,
      doviz_birimi: dovizBirimi,
      kur_carpanii: "1,00",
      skip_tcmb: true
    }
  }];
}

// Tarihi hem nokta (.) hem tire (-) ayracını destekleyecek şekilde parse et
const ayirac = faturaStr.includes('.') ? '.' : '-';
const parcalar = faturaStr.split(ayirac).map(Number);

if (parcalar.length !== 3 || parcalar.some(isNaN)) {
  throw new Error("Tarih parse edilemedi. Gelen değer: '" + faturaStr + "'. Beklenen format: DD-MM-YYYY veya DD.MM.YYYY");
}

const [gun, ay, yil] = parcalar;
let tarih = new Date(yil, ay - 1, gun);

if (isNaN(tarih.getTime())) {
  throw new Error("Geçersiz tarih oluştu. Girdi: " + faturaStr);
}

tarih.setDate(tarih.getDate() - 1);
while (tarih.getDay() === 0 || tarih.getDay() === 6) {
  tarih.setDate(tarih.getDate() - 1);
}

const dd = String(tarih.getDate()).padStart(2, '0');
const mm = String(tarih.getMonth() + 1).padStart(2, '0');
const yyyy = tarih.getFullYear();
const yyMM = `${yyyy}${mm}`;

const tcmbUrl = `https://www.tcmb.gov.tr/kurlar/${yyMM}/${dd}${mm}${yyyy}.xml`;

return [{
  json: {
    ...data,
    tcmb_url: tcmbUrl,
    doviz_birimi: dovizBirimi,
    kur_tarihi: `${dd}-${mm}-${yyyy}`,
    skip_tcmb: false
  }
}];

const aaa = $('Code in JavaScript4').first().json;

if (aaa.skip_tcmb) {
  const urunler = (aaa.urunler || []).map(urun => ({
    ...urun,
    kur_carpani: "1,00",
    toplam_tl: urun.birim_fiyat // veya ilgili tutar alanı
  }));
  return [{ json: { ...aaa, urunler, kur_carpanii: "1,00" } }];
}

// ... mevcut XML parse kodu buradan devam eder
const xmlText = items[0].json.data;
const oncekiVeri = $('Code in JavaScript4').first().json;
const doviz = oncekiVeri.doviz_birimi;

let kur, kurVirgul;

if (!doviz || doviz === 'TL' || doviz === 'TRY') {
  kur = 1;
  kurVirgul = '1,00';
} else {
  const regex = new RegExp(
    `<Currency[^>]*CurrencyCode="${doviz}"[^>]*>[\\s\\S]*?<ForexBuying>([\\d.]+)<\\/ForexBuying>`,
    'i'
  );

  const match = xmlText.match(regex);

  if (!match) {
    throw new Error(`${doviz} kuru bulunamadı.`);
  }

  kur = parseFloat(match[1]);
  kurVirgul = match[1].replace('.', ',');
}

const urunler = oncekiVeri.urunler.map(urun => {
  const fiyat = parseFloat(String(urun.birim_fiyat).replace(',', '.'));
  const miktar = parseFloat(String(urun.miktar).replace(',', '.'));
  const toplamTL = (fiyat * miktar * kur).toFixed(2).replace('.', ',');

  return {
    ...urun,
    kur_carpani: kurVirgul,
    toplam_tl: toplamTL
  };
});

return [{
  json: {
    ...oncekiVeri,
    urunler: urunler,
    kur_carpanii: kurVirgul
  }
}];

const raw = item.json.content?.[0]?.text || "";

if (!raw.trim()) {
  throw new Error("Message a model2 boş yanıt döndürdü. Girdi: " + JSON.stringify(item.json).slice(0, 500));
}

let clean = raw.replace(/```json\s*/gi, '').replace(/```/g, '').trim();

let parsed;
try {
  const asIs = JSON.parse(clean);
  parsed = Array.isArray(asIs) ? asIs[0] : asIs;
} catch (err) {
  const first = clean.indexOf('{');
  const last = clean.lastIndexOf('}');
  if (first === -1 || last === -1 || last <= first) {
    throw new Error("Geçerli JSON bulunamadı. Ham çıktı: " + clean.slice(0, 500));
  }
  parsed = JSON.parse(clean.substring(first, last + 1));
}

if (typeof parsed.stok === 'string') {
  parsed.stok = parsed.stok.toLowerCase() === 'true';
}

const orijinalUrun = $('Merge').item.json.urunler;
parsed.miktar = orijinalUrun?.miktar ?? "";
parsed["birim fiyat"] = orijinalUrun?.birim_fiyat ?? "";

return {
  json: {
    message: { content: parsed }
  }
};

const gorulen = new Set();
const satirlar = [];

for (const item of items) {
  const firma = item.json['Şirket ismi'];
  const vkn = item.json['VKN'];
  if (!firma || !vkn) continue;

  const firmaStr = String(firma).trim();
  const vknStr = String(vkn).trim();

  const anahtar = firmaStr.toLowerCase() + '|' + vknStr;
  if (gorulen.has(anahtar)) continue;
  gorulen.add(anahtar);

  satirlar.push(`${firmaStr} - ${vknStr}`);
}

return [{ json: { cari_listesi: satirlar.join('\n') } }];

